CREATE TABLE lead_intake_r101b (  request_id TEXT PRIMARY KEY NOT NULL,  received_at TEXT NOT NULL,  expires_at TEXT NOT NULL,  schema TEXT NOT NULL CHECK (schema = 'ai-skill-lab.lead.v2'),  name TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 80),  audience TEXT NOT NULL CHECK (audience IN ('adult','parent','teen','business')),  contact TEXT NOT NULL CHECK (length(contact) BETWEEN 1 AND 120),  goal TEXT NOT NULL DEFAULT '' CHECK (length(goal) <= 600),  program TEXT NOT NULL DEFAULT '' CHECK (length(program) <= 80),  locale TEXT NOT NULL CHECK (locale IN ('ru','en')),  privacy_consent INTEGER NOT NULL CHECK (privacy_consent = 1),  adult_confirmed INTEGER NOT NULL CHECK (adult_confirmed IN (0,1)),  source TEXT NOT NULL CHECK (source = 'ai-skill-lab'),  source_path TEXT CHECK (source_path IS NULL OR length(source_path) <= 180),  CHECK (expires_at > received_at));
